window.BOOK={"key":"kharida","app":"mutoon-kharida","lsk":"mutoon_kharida_v1","prefix":"kh_","title":"الخريدة البهية","sub":"العقيدة · أحمد الدردير المالكي (ت ١٢٠١هـ) · ٧١ بيتًا","poems":[{"id":"kharida","title":"الخريدة البهية","nazim":"أبو البركات أحمد بن محمد الدردير العدوي المالكي","death":"ت ١٢٠١هـ","meter":"الرجز","source":"جامع الكتب الإسلامية (عن الشاملة الذهبية): الخريدة البهية في علم التوحيد","srcUrl":"https://ketabonline.com/ar/books/102218","note":"النص المشكول من نشرة الشاملة الذهبية (٧١ بيتًا)، قوبل آليًّا بنسخة مشكولة مستقلة وبشرح الدردير نفسه (موقع «مكتبة تراث الأمة» ونشرة مطبوعة محققة)، ومنها كُمّل الشكل وصُحّحت أخطاء طباعية يسيرة.","verses":[["يَقُولُ رَاجِيْ رَحْمَةِ الْقَدِيرِ","أَيْ أَحْمَدُ الْمَشْهُورُ بِالدَّرْدِيرِ"],["الْحَمْدُ للهِ الْعَلِيِّ الْوَاحِدِ","الْعَالِمِ الْفَرْدِ الْغَنِيِّ الْمَاجِدِ"],["وَأَفْضَلُ الصَّلَاةِ وَالتَّسْلِيمِ","عَلَى النَّبِيِّ الْمُصْطَفَى الْكَرِيمِ"],["وَآلِهِ وَصَحْبِهِ الْأَطْهَارِ","لَا سِيَّمَا رَفِيقُهُ فِي الْغَارِ"],["وَهَذِهِ عَقِيدَةٌ سَنِيَّهْ","سَمَّيْتُهَا الْخَرِيدَةَ الْبَهِيَّهْ"],["لَطِيْفَةٌ صَغِيرَةٌ فِي الْحَجْمِ","لَكِنَّهَا كَبِيرَةٌ فِي الْعِلْمِ"],["تَكْفِيْكَ عِلْمًا إِنْ تُرِدْ أَنْ تَكْتَفِيْ","لِأَنَّهَا بِزُبْدَةِ الْفَنِّ تَفِيْ"],["وَاللهَ أَرْجُو فِي قَبُولِ الْعَمَلِ","وَالنَّفْعَ مِنْهَا ثُمَّ غَفْرَ الزَّلَلِ"],["أَقْسَامُ حُكْمِ الْعَقْلِ لَا مَحَالَهْ","هِيَ الْوُجُوبُ ثُمَّ الِاسْتِحَالَهْ"],["ثُمَّ الْجَوَازُ ثَالِثُ الْأَقْسَامِ","فَافْهَمْ مُنِحْتَ لَذَّةَ الْأَفْهَامِ"],["وَوَاجِبٌ شَرْعًا عَلَى الْمُكَلَّفِ","مَعْرِفَةُ اللهِ الْعَلِيِّ فَاعْرِفِ"],["أَيْ يَعْرِفُ الْوَاجِبَ وَالْمُحَالَا","مَعْ جَائِزٍ فِي حَقِّهِ تَعَالَى"],["وَمِثْلُ ذَا فِي حَقِّ رُسْلِ اللهِ","عَلَيْهِمِ تَحِيَّةُ الْإِلَهِ"],["فَالْوَاجِبُ الْعَقْلِيُّ مَا لَمْ يَقْبَلِ","الِانْتِفَا فِي ذَاتِهِ فَابْتَهِلِ"],["وَالْمُسْتَحِيلُ كُلُّ مَا لَمْ يَقْبَلِ","فِي ذَاتِهِ الثُّبُوتَ ضِدَّ الْأَوَّلِ"],["وَكُلُّ أَمْرٍ قَابِلٍ لِلِانْتِفَا","وَلِلثُّبُوتِ جَائِزٌ بِلَا خَفَا"],["ثُمَّ اعْلَمَنْ بِأَنَّ هَذَا الْعَالَمَا","أَيْ مَا سِوَى اللهِ الْعَلِيِّ الْعَالِمَا"],["مِنْ غَيْرِ شَكٍّ حَادِثٌ مُفْتَقِرُ","لِأَنَّهُ قَامَ بِهِ التَّغَيُّرُ"],["حُدُوثُهُ وُجُودُهُ بَعْدَ الْعَدَمْ","وَضِدُّهُ هُوَ الْمُسَمَّى بِالْقِدَمْ"],["فَاعْلَمْ بِأَنَّ الْوَصْفَ بِالْوُجُودِ","مِنْ وَاجِبَاتِ الْوَاحِدِ الْمَعْبُودِ"],["إِذْ ظَاهِرٌ بِأَنَّ كُلَّ أَثَرِ","يَهْدِي إِلَى مُؤَثِّرٍ فَاعْتَبِرِ"],["وَذِي تُسَمَّى صِفَةً نَفْسِيَّهْ","ثُمَّ تَلِيهَا خَمْسَةٌ سَلْبِيَّهْ"],["وَهِيَ الْقِدَمْ بِالذَّاتِ فَاعْلَمْ وَالْبَقَا","قِيَامُهُ بِنَفْسِهِ نِلْتَ التُّقَى"],["تَخَالُفٌ لِلْغَيْرِ وَحْدَانِيَّهْ","فِي الذَّاتِ أَوْ صِفَاتِهِ الْعَلِيَّهْ"],["وَالْفِعْلِ فَالتَّأْثِيرُ لَيْسَ إِلَّا","لِلْوَاحِدِ الْقَهَّارِ جَلَّ وَعَلَا"],["وَمَنْ يَقُلْ بِالطَّبْعِ أَوْ بِالْعِلَّهْ","فَذَاكَ كُفْرٌ عِنْدَ أَهْلِ الْمِلَّهْ"],["وَمَنْ يَقُلْ بِالْقُوَّةِ الْمُودَعَةِ","فَذَاكَ بِدْعِيٌّ فَلَا تَلْتَفِتِ"],["لَوْ لَمْ يَكُنْ مُتَّصِفًا بِهَا لَزِمْ","حُدُوثُهُ وَهْوَ مُحَالٌ فَاسْتَقِمْ"],["لِأَنَّهُ يُفْضِيْ إِلَى التَّسَلْسُلِ","وَالدَّوْرِ وَهْوَ الْمُسْتَحِيلُ الْمُنْجَلِي"],["فَهْوَ الْجَلِيلُ وَالْجَمِيلُ وَالْوَلِيْ","وَالظَّاهِرُ الْقُدُّوْسُ وَالرَّبُّ الْعَلِيْ"],["مُنَزَّهٌ عَنِ الْحُلُولِ وَالْجِهَهْ","وَالِاتِّصَالِ الِانْفِصَالِ وَالسَّفَهْ"],["ثُمَّ الْمَعَانِي سَبْعَةٌ لِلرَّائِي","أَيْ عِلْمُهُ الْمُحِيطُ بِالْأَشْيَاءِ"],["حَيَاتُهُ وَقُدْرَةٌ إِرَادَهْ","وَكُلُّ شَيْءٍ كَائِنٌ أَرَادَهْ"],["وَإِنْ يَكُنْ بِضِدِّهِ قَدْ أَمَرَا","فَالْقَصْدُ غَيْرُ الْأَمْرِ فَاطْرَحِ الْمِرَا"],["فَقَدْ عَلِمْتَ أَرْبَعًا أَقْسَامَا","فِي الْكَائِنَاتِ فَاحْفَظِ الْمَقَامَا"],["كَلَامُهُ وَالسَّمْعُ وَالْإِبْصَارُ","فَهْوَ الْإِلَهُ الْفَاعِلُ الْمُخْتَارُ"],["وَوَاجِبٌ تَعْلِيقُ ذِي الصِّفَاتِ","حَتْمًا دَوَامًا مَا عَدَا الْحَيَاةِ"],["فَالْعِلْمُ جَزْمًا وَالْكَلَامُ السَّامِي","تَعَلَّقَا بِسَائِرِ الْأَقْسَامِ"],["وَقُدْرَةٌ إِرَادَةٌ تَعَلَّقَا","بِالْمُمْكِنَاتِ كُلِّهَا أَخَا التُّقَى"],["وَاجْزِمْ بِأَنَّ سَمْعَهُ وَالْبَصَرَا","تَعَلَّقَا بِكُلِّ مَوْجُودٍ يُرَى"],["وَكُلُّهَا قَدِيمَةٌ بِالذَّاتِ","لِأَنَّهَا لَيْسَتْ بِغَيْرِ الذَّاتِ"],["ثُمَّ الْكَلَامُ لَيْسَ بِالْحُرُوفِ","وَلَيْسَ بِالتَّرْتِيبِ كَالْمَأْلُوفِ"],["وَيَسْتَحِيلُ ضِدُّ مَا تَقَدَّمَا","مِنَ الصِّفَاتِ الشَّامِخَاتِ فَاعْلَمَا"],["لِأَنَّهُ لَوْ لَمْ يَكُنْ مَوْصُوفَا","بِهَا لَكَانَ بِالسِّوَى مَعْرُوفَا"],["وَكُلُّ مَنْ قَامَ بِهِ سِوَاهَا","فَهْوَ الَّذِي فِي الْفَقْرِ قَدْ تَنَاهَى"],["وَالْوَاحِدُ الْمَعْبُودُ لَا يَفْتَقِرُ","لِغَيْرِهِ جَلَّ الْغَنِيْ الْمُقْتَدِرُ"],["وَجَائِزٌ فِي حَقِّهِ الْإِيجَادُ","وَالتَّرْكُ وَالْإِشْقَاءُ وَالْإِسْعَادُ"],["وَمَنْ يَقُلْ فِعْلُ الصَّلَاحِ وَجَبَا","عَلَى الْإِلَهِ قَدْ أَسَاءَ الْأَدَبَا"],["وَاجْزِمْ أَخِي بِرُؤْيَةِ الْإِلَهِ","فِي جَنَّةِ الْخُلْدِ بِلَا تَنَاهِي"],["إِذِ الْوُقُوعُ جَائِزٌ بِالْعَقْلِ","وَقَدْ أَتَى فِيهِ دَلِيلُ النَّقْلِ"],["وَصِفْ جَمِيعَ الرُّسْلِ بِالْأَمَانَهْ","وَالصِّدْقِ وَالتَّبْلِيغِ وَالْفَطَانَهْ"],["وَيَسْتَحِيلُ ضِدُّهَا عَلَيْهِمُ","وَجَائِزٌ كَالْأَكْلِ فِي حَقِّهِمُ"],["إِرْسَالُهُمْ تَفَضُّلٌ وَرَحْمَهْ","لِلْعَالَمِيْنَ جَلَّ مُولِي النِّعْمَهْ"],["وَيَلْزَمُ الْإِيمَانُ بِالْحِسَابِ","وَالْحَشْرِ وَالْعِقَابِ وَالثَّوَابِ"],["وَالنَّشْرِ وَالصِّرَاطِ وَالْمِيزَانِ","وَالْحَوْضِ وَالنِّيرَانِ وَالْجِنَانِ"],["وَالْجِنِّ وَالْأَمْلَاكِ ثُمَّ الْأَنْبِيَا","وَالْحُورِ وَالْوِلْدَانِ ثُمَّ الْأَوْلِيَا"],["وَكُلِّ مَا جَاءَ عَنِ الْبَشِيرِ","مِنْ كُلِّ حُكْمٍ صَارَ كَالضَّرُورِي"],["وَيَنْطَوِي فِي كِلْمَةِ الْإِسْلَامِ","مَا قَدْ مَضَى مِنْ سَائِرِ الْأَحْكَامِ"],["فَأَكْثِرَنْ مِنْ ذِكْرِهَا بِالْأَدَبِ","تَرْقَى بِهَذَا الذِّكْرِ أَعْلَى الرُّتَبِ"],["وَغَلِّبِ الْخَوْفَ عَلَى الرَّجَاءِ","وَسِرْ لِمَوْلَاكَ بِلَا تَنَاءِ"],["وَجَدِّدِ التَّوْبَةَ لِلْأَوْزَارِ","لَا تَيْأَسَنْ مِنْ رَحْمَةِ الْغَفَّارِ"],["وَكُنْ عَلَى آلَائِهِ شَكُورَا","وَكُنْ عَلَى بَلَائِهِ صَبُورَا"],["فَكُلُّ أَمْرٍ بِالْقَضَاءِ وَالْقَدَرْ","وَكُلُّ مَقْدُورٍ فَمَا عَنْهُ مَفَرْ"],["فَكُنْ لَهُ مُسَلِّمًا كَيْ تَسْلَمَا","وَاتْبَعْ سَبِيلَ النَّاسِكِينَ الْعُلَمَا"],["وَخَلِّصِ الْقَلْبَ مِنَ الْأَغْيَارِ","بِالْجِدِّ وَالْقِيَامِ فِي الْأَسْحَارِ"],["وَالْفِكْرِ وَالذِّكْرِ عَلَى الدَّوَامِ","مُجْتَنِبًا لِسَائِرِ الْآثَامِ"],["مُرَاقِبًا للهِ فِي الْأَحْوَالِ","لِتَرْتَقِيْ مَعَالِمَ الْكَمَالِ"],["وَقُلْ بِذُلٍّ رَبِّ لَا تَقْطَعْنِي","عَنْكَ بِقَاطِعٍ وَلَا تَحْرِمْنِي"],["مِنْ سِرِّكَ الْأَبْهَى الْمُزِيلِ لِلْعَمَى","وَاخْتِمْ بِخَيْرٍ يَا رَحِيمَ الرُّحَمَا"],["وَالْحَمْدُ للهِ عَلَى الْإِتْمَامِ","وَأَفْضَلُ الصَّلَاةِ وَالسَّلَامِ"],["عَلَى النَّبِيِّ الْهَاشِمِيِّ الْخَاتِمِ","وَآلِهِ وَصَحْبِهِ الْأَكَارِمِ"]],"secs":{"1":"المنظومة"}}],"sharh":false};
